class Solution:
    def closestFair(self, n: int) -> int:
        def fair(k):
            e = o = 0
            while k:
                if (k % 10) % 2 == 0:
                    e += 1
                else:
                    o += 1
                k //= 10
            return e == o
        while not fair(n):
            n += 1
        return n

