class Solution {
    public int closestFair(int n) {
        long k = n;
        if (digits(k) % 2 == 1) k = pow10(digits(k));
        while (true) {
            int d = digits(k);
            if (d % 2 == 1) { k = pow10(d); continue; }
            if (fair(k)) return (int) k;
            k++;
        }
    }
    private int digits(long k) { int d = 0; while (k > 0) { d++; k /= 10; } return d; }
    private long pow10(int d) { long r = 1; while (d-- > 0) r *= 10; return r; }
    private boolean fair(long k) {
        int e = 0, o = 0;
        while (k > 0) { if ((k % 10) % 2 == 0) e++; else o++; k /= 10; }
        return e == o;
    }
}

